	//function for exporting account period details
	function account_period()
	{
		$this->common_model->check_admin_authorization();
		session_start();

		require_once 'static/classes/Classes/PHPExcel.php';
		require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

		// Create new PHPExcel object
		$objPHPExcel = new PHPExcel();
		//set column width
		$objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
		$objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(20);
		$objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(30);
		$objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(30);
		$objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(20);

		$objPHPExcel->getActiveSheet()->setCellValue('A1', SLNO);
		$objPHPExcel->getActiveSheet()->setCellValue('B1', YEARREF);
		$objPHPExcel->getActiveSheet()->setCellValue('C1', ACCSTARTDATE);
		$objPHPExcel->getActiveSheet()->setCellValue('D1', ACCENDDATE);
		$objPHPExcel->getActiveSheet()->setCellValue('E1', ACCSTATUS);

		$objPHPExcel->getActiveSheet()->getStyle('A1:E1')->applyFromArray(
		array('fill' 	=> array(
								'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
								'color'		=> array('argb' => 'FF306EFF'),
							),
		  'borders' => array(
								'top'	 => array('style' => PHPExcel_Style_Border::BORDER_THICK),
								'right'	 => array('style' => PHPExcel_Style_Border::BORDER_THICK)
							)
		 )
	);

		$sqlArray    = $this->db->query($_SESSION['sess_query']);
		$colVal      = 3;
		if ($sqlArray->num_rows() > 0)
		{
			foreach ($sqlArray->result() as $key=>$row)
			{
				$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $key+1);
				$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($row->vYearRef));
				$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, ($row->dSDate != '0000-00-00')?date('d-m-Y',strtotime($row->dSDate)):'NIL');
				$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, ($row->dEDate != '0000-00-00')?date('d-m-Y',strtotime($row->dEDate)):'NIL');
				$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, ($row->vActive == 'O')?ACCOPEN:ACCCLOSED);

				$colVal++;
			}//end for each
		}//end if

		// Rename sheet
		$objPHPExcel->getActiveSheet()->setTitle(ACCOUNTPERIOD);
		$objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

		// Redirect output to a client's web browser (Excel5)
		header('Content-Type: application/vnd.ms-excel');
		header('Content-Disposition: attachment;filename="accountperiod_'.date('Y-m-d').'_'.time().'.xls"');
		header('Cache-Control: max-age=0');
		$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
		$objWriter->save('php://output');
	}//end function

    //function for exporting employee details
    function employee()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(10);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(45);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('I')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('J')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('K')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('L')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('M')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('N')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('O')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('P')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('Q')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('R')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('S')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('T')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('U')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('V')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('W')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('X')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('Y')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('Z')->setWidth(30);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', SLNO);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', ACCCODENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', TRANSCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', EMPNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('F1', LOCATIONADDR);
        $objPHPExcel->getActiveSheet()->setCellValue('G1', COMPANYEMAIL);
        $objPHPExcel->getActiveSheet()->setCellValue('H1', LOCATIONPHONE);
        $objPHPExcel->getActiveSheet()->setCellValue('I1', CUSTMOBILE);
        $objPHPExcel->getActiveSheet()->setCellValue('J1', COMPANYCOUNTRY);
        $objPHPExcel->getActiveSheet()->setCellValue('K1', CURRNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('L1', IDTYPE);
        $objPHPExcel->getActiveSheet()->setCellValue('M1', IDDETAILS);
        $objPHPExcel->getActiveSheet()->setCellValue('N1', CREDITDAYS);
        $objPHPExcel->getActiveSheet()->setCellValue('O1', AMOUNT);
        $objPHPExcel->getActiveSheet()->setCellValue('P1', CUSTSERVCALC);
        $objPHPExcel->getActiveSheet()->setCellValue('Q1', SERVAMT);
        $objPHPExcel->getActiveSheet()->setCellValue('R1', CUSTDISCCALC);
        $objPHPExcel->getActiveSheet()->setCellValue('S1', DISCAMT);
        $objPHPExcel->getActiveSheet()->setCellValue('T1', GALLILEOCD);
        $objPHPExcel->getActiveSheet()->setCellValue('U1', AMADEUSCD);
        $objPHPExcel->getActiveSheet()->setCellValue('V1', SABRE);
        $objPHPExcel->getActiveSheet()->setCellValue('W1', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('X1', EMPDESNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('Y1', EMPLOANAC);
        $objPHPExcel->getActiveSheet()->setCellValue('Z1', LOCATIONNAME);

        $objPHPExcel->getActiveSheet()->getStyle('A1:Z1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 3;
        if ($sqlArray->num_rows() > 0)
        {
            foreach ($sqlArray->result() as $key=>$row)
            {
                $locId       = array_filter(@split(',',$row->vLocations));
                $locName     = $this->common_model->getLocationName($locId);

                switch($row->vIdType)
                {
                    case "C" :
                        $idType	= 'Civil Id';
                        break;

                    case "PASS" :
                        $idType	= 'Passport';
                        break;

                    case "L" :
                        $idType	= 'License';
                        break;

                    case "ID" :
                        $idType	= 'Id Card';
                        break;
                }//end switch

                $servCal   = ($row->vServCalc == 'F')?'Fixed':'Percentage';
                $discCal   = ($row->vDiscCalc == 'F')?'Fixed':'Percentage';

                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $key+1);
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, ($row->dDate != '0000-00-00')?date('d-m-Y',strtotime($row->dDate)):'NIL');
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($this->common_model->get_field_name('AccountHeadAccounts',                                                                       'vTitle'," WHERE nId='".$row->nFId."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row->vCode));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($row->vName));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($row->vAddress));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($row->vEmail));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($row->vPhone));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($row->vMobile));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($this->common_model->get_field_name('Country','vName'," WHERE nId='".$row->nCountry."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($this->common_model->get_field_name('Currency','vTitle'," WHERE nId='".$row->nCurrency."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($idType));
                $objPHPExcel->getActiveSheet()->setCellValue('M'.$colVal, stripslashes($row->vCivilId));
                $objPHPExcel->getActiveSheet()->setCellValue('N'.$colVal, stripslashes($row->vCreditDays));
                $objPHPExcel->getActiveSheet()->setCellValue('O'.$colVal, stripslashes($row->vAmount));
                $objPHPExcel->getActiveSheet()->setCellValue('P'.$colVal, stripslashes($servCal));
                $objPHPExcel->getActiveSheet()->setCellValue('Q'.$colVal, stripslashes($row->vServCal));
                $objPHPExcel->getActiveSheet()->setCellValue('R'.$colVal, stripslashes($discCal));
                $objPHPExcel->getActiveSheet()->setCellValue('S'.$colVal, stripslashes($row->vDiscCal));
                $objPHPExcel->getActiveSheet()->setCellValue('T'.$colVal, stripslashes($row->vGallileoCD));
                $objPHPExcel->getActiveSheet()->setCellValue('U'.$colVal, stripslashes($row->vAmadeusCD));
                $objPHPExcel->getActiveSheet()->setCellValue('V'.$colVal, stripslashes($row->vSabre));
                $objPHPExcel->getActiveSheet()->setCellValue('W'.$colVal, stripslashes($row->vLocation));
                $objPHPExcel->getActiveSheet()->setCellValue('X'.$colVal, stripslashes($this->common_model->get_field_name('Employee','vTitle', " WHERE nId='".$row->nDesignation."' ").'( '.$this->common_model->get_field_name('Employee','vCode', " WHERE nId='".$row->nDesignation."' ").'  )'));
                $objPHPExcel->getActiveSheet()->setCellValue('Y'.$colVal, stripslashes($this->common_model->get_field_name('AccountHeadAccounts','vTitle', " WHERE nId='".$row->nGroupMgr."'").'( '.$this->common_model->get_field_name('AccountHeadAccounts','vACode', " WHERE nId='".$row->nGroupMgr."' ").'  )'));
                $objPHPExcel->getActiveSheet()->setCellValue('Z'.$colVal, stripslashes($locName));

                $colVal++;
            }//end for each
        }//end if

        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(EMPDETAILS);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="employee_'.date('Y-m-d').'_'.time().'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

