        $objPHPExcel->getActiveSheet()->setCellValue('L1', CURRNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('M1', RATE);
        $objPHPExcel->getActiveSheet()->setCellValue('N1', AMOUNTFC);
        $objPHPExcel->getActiveSheet()->setCellValue('O1', AMOUNTDC);
        $objPHPExcel->getActiveSheet()->setCellValue('P1', REFDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('Q1', REFNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('R1', ENTEREDBY);
        $objPHPExcel->getActiveSheet()->setCellValue('S1', REFNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('T1', REMARKS);
        $objPHPExcel->getActiveSheet()->setCellValue('U1', DESCRIPTION);
        $objPHPExcel->getActiveSheet()->setCellValue('V1', INVOICE);
        $objPHPExcel->getActiveSheet()->setCellValue('W1', INVOICEDATE);

        $objPHPExcel->getActiveSheet()->getStyle('A1:W1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 3;
        if ($sqlArray->num_rows() > 0)
        {
            foreach ($sqlArray->result() as $key=>$row)
            {
                $divName    = $this->common_model->get_field_name('Division','vTitle'," WHERE nId = '".$row->nDivision."'");
                $locName    = $this->common_model->get_field_name('Location','vCode'," WHERE nId = '".$row->vLocation."'");

                $count      = $key+1;
                $dDate      = ($row->dDate != '0000-00-00')?date('d-m-Y',strtotime($row->dDate)):'NIL';
                $dRefDate   = ($row->dRefDate != '0000-00-00')?date('d-m-Y',strtotime($row->dRefDate)):'NIL';
                $dInvDate   = ($row->dInvoiceDate != '0000-00-00')?date('d-m-Y',strtotime($row->dInvoiceDate)):'NIL';
                $chequeDate = ($row->dChequeDate != '0000-00-00')?date('d-m-Y',strtotime($row->dChequeDate)):'NIL';

                switch($row->vTransMode)
                {
                    case "Cr" :
                        $modeofPay	= 'Credit';
                        break;

                    case "Ca" :
                        $modeofPay	= 'Cash';
                        break;

                    case "Dr" :
                        $modeofPay	= 'Debit';
                        break;
                }//end switch

                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $count);
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($divName));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($locName));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $dDate);
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($this->common_model->get_field_name('Transactions','vTitle'," WHERE nId='".$row->nTransaction."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($row->vDocNumber));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($modeofPay));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($chequeDate));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($row->vChequeNumber));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$row->nAcCode."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$row->vSubCode."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($this->common_model->get_field_name('Currency','vTitle'," WHERE nId='".$row->nCurrency."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('M'.$colVal, stripslashes($row->vRate));
                $objPHPExcel->getActiveSheet()->setCellValue('N'.$colVal, stripslashes($row->vAmountFC));
                $objPHPExcel->getActiveSheet()->setCellValue('O'.$colVal, stripslashes($row->vAmountDC));
                $objPHPExcel->getActiveSheet()->setCellValue('P'.$colVal, stripslashes($dRefDate));
                $objPHPExcel->getActiveSheet()->setCellValue('Q'.$colVal, stripslashes($row->vRefNumber));
                $objPHPExcel->getActiveSheet()->setCellValue('R'.$colVal, stripslashes($row->vEnteredBy));
                $objPHPExcel->getActiveSheet()->setCellValue('S'.$colVal, stripslashes($row->vRefName));
                $objPHPExcel->getActiveSheet()->setCellValue('T'.$colVal, stripslashes($row->vRemarks));
                $objPHPExcel->getActiveSheet()->setCellValue('U'.$colVal, stripslashes($row->vDes));
                $objPHPExcel->getActiveSheet()->setCellValue('V'.$colVal, stripslashes($row->vInvoice));
                $objPHPExcel->getActiveSheet()->setCellValue('W'.$colVal, stripslashes($dInvDate));

                $colVal 	     = $colVal+1;
                $viewAccessRow   = array();
                $viewAccessList  = $this->db->query("SELECT * FROM {PRE}BankBookDetails WHERE nBankbookId ='".$row->nBBId."'");
                if($viewAccessList->num_rows() > 0)
