															WHEN acc.vSubSale = '1' THEN 'Yes'
														WHEN acc.vSubSale = '0' THEN 'No'
															WHEN acc.vSubSale = 'C' THEN 'Cash A/C'
														WHEN acc.vSubSale = 'S' THEN 'Sales'
															WHEN acc.vSubSale = 'P' THEN 'P & L Earing'
														WHEN acc.vSubSale = 'A' THEN 'Advance'
															ELSE 'Bank' END as SubSale,CASE WHEN acc.vAllocation = '1' THEN 'Yes' ELSE 'No' END as Allocation,CASE WHEN
                                                acc.vRefund = '1' THEN 'Yes' ELSE 'No' END as Refund,
														CASE vSLedgerAuto
															WHEN acc.vSubLedger = 'O' THEN 'Other'
															ELSE 'Sub Ledger' END as SubLedger,
														CASE
															WHEN acc.vSubLedgerType = 'C' THEN 'Customer'
														WHEN acc.vSubLedgerType = 'O' THEN 'Others'
															WHEN acc.vSubLedgerType = 'V' THEN 'Vendor'
														WHEN acc.vSubLedgerType = 'E' THEN 'Employee'
															WHEN acc.vSubLedgerType = 'A' THEN 'Agent'
															ELSE 'Normal' END as SubLedgerType,
														CASE
															WHEN acc.vSLedgerAuto = '1' THEN 'Yes'
															ELSE 'No' END as SLedgerAuto
													 FROM {PRE}AccountHead ach
														LEFT JOIN {PRE}AccountHeadAccounts aca ON ach.nAId = aca.nHAId
													 LEFT JOIN {PRE}AccountHeadControls acc ON aca.nId = acc.nActHId
													  AND ach.nAId = acc.nHAId
														WHERE ach.nAId = '".$row->nAId."' GROUP BY aca.nId ORDER BY
														ach.nAId DESC");
				if($viewAccessList->num_rows() > 0)
				{
					$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, ACCCODENAME);
					$objPHPExcel->getActiveSheet()->getStyle('A'.$colVal)->applyFromArray(
