						$month = 'June';
					break;

					case "07" :
						$month = 'July';
					break;

					case "08" :
						$month = 'August';
					break;

					case "09" :
						$month = 'September';
					break;

					case "10" :
						$month = 'October';
					break;

					case "11" :
						$month = 'November';
					break;

					case "12" :
						$month = 'December';
					break;
				}//end switch
