				$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $key+1);
				$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($month));
				$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row->vYear));
				$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($this->common_model->get_field_name('Division','vTitle'," WHERE nId = '".$row->nDivision."'")));
				$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($locName));

				$colVal 	     = $colVal+1;
				$viewAccessRow   = array();
				$viewAccessList  = $this->db->query("SELECT b.nBId as bId,b.nTotal,bd.*,bd.nId as 																			                                                       bdId,b.vLocation,b.vYear,b.vCopyref,b.vDocNumber,
													  aha.*,aha.vTitle as accName,aha.vACode as accCode,
													  CASE
														WHEN bd.vMode = 'Cr' THEN 'Credit'
													  ELSE 'Debit' END as mode FROM {PRE}BudgetDetails
														bd LEFT JOIN {PRE}Budget b
													 ON b.nBId = bd.nBudId
													  LEFT JOIN {PRE}AccountHeadAccounts aha ON bd.nAHAId = aha.nId
													 WHERE b.nBId='".$row->nBId."' ORDER BY bd.nId DESC");
				if($viewAccessList->num_rows() > 0)
				{
					$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, ACCCODENAME);
					$objPHPExcel->getActiveSheet()->getStyle('A'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, ACCNAME);
					$objPHPExcel->getActiveSheet()->getStyle('B'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, BUDGETMODE);
					$objPHPExcel->getActiveSheet()->getStyle('C'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, BUDGETAMOUNT);
					$objPHPExcel->getActiveSheet()->getStyle('D'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$colVal		 = $colVal+1;
					foreach ($viewAccessList->result() as $key1=>$row1)
					{
						$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($row1->accCode));
						$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($row1->accName));
						$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row1->mode));
						$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row1->nAmount));

						$colVal++;
					}//end foreach
				    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, TOTAL);
					$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row1->nTotal));

				}//end if
				$colVal++;
			}//end for each
		}//end if

		// Rename sheet
		$objPHPExcel->getActiveSheet()->setTitle(BUDGETDETAILS);
		$objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

		// Redirect output to a client's web browser (Excel5)
		header('Content-Type: application/vnd.ms-excel');
		header('Content-Disposition: attachment;filename="budget_'.date('Y-m-d').'_'.time().'.xls"');
		header('Cache-Control: max-age=0');
		$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
		$objWriter->save('php://output');
	}//end function

