                $objPHPExcel->getActiveSheet()->setCellValue('P'.$colVal, stripslashes($row->vPhone));
                $objPHPExcel->getActiveSheet()->setCellValue('Q'.$colVal, stripslashes($row->vEmail));
                $objPHPExcel->getActiveSheet()->setCellValue('R'.$colVal, stripslashes($row->vAddress));

