											)
						 )
					);

					$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, STOCKQTY);
				    $objPHPExcel->getActiveSheet()->getStyle('E'.$colVal)->applyFromArray(
						array('fill' 	=> array(
												'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
												'color'		=> array('argb' => 'FFFBB917'),
											)
						 )
					);
				    $objPHPExcel->getActiveSheet()->getStyle('F'.$colVal)->applyFromArray(
						array('fill' 	=> array(
												'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
