		{
			foreach ($sqlArray->result() as $key=>$row)
			{
				$locId      = array_filter(@split(',',$row->vLocation));
				$locName    = $this->common_model->getLocationName($locId);

				$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $key+1);
				$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($row->vTitle));
				$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row->vFYear));
				$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row->vTYear));
				$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($row->dFDate));
				$objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($row->dTDate));

				$colVal 	     = $colVal+1;
				$viewAccessRow   = array();
				$viewAccessList  = $this->db->query("SELECT yc.*,ycd.*,
													  aha.vTitle as accName,aha.vACode as accCode,
													  CASE
														WHEN ycd.vMode = 'Cr' THEN 'Credit'
													  ELSE 'Debit' END as mode FROM {PRE}YearClosingDetails
														ycd LEFT JOIN {PRE}YearClosing yc
													 ON yc.nYCId = ycd.nYearCId
													  LEFT JOIN {PRE}AccountHeadAccounts aha ON ycd.nAHAId = aha.nId
													 WHERE yc.nYCId='".$row->nYCId."' ORDER BY ycd.nId DESC");
				if($viewAccessList->num_rows() > 0)
				{
					$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, ACCCODENAME);
					$objPHPExcel->getActiveSheet()->getStyle('A'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, ACCNAME);
					$objPHPExcel->getActiveSheet()->getStyle('B'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, BUDGETMODE);
					$objPHPExcel->getActiveSheet()->getStyle('C'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, AMOUNTFC);
					$objPHPExcel->getActiveSheet()->getStyle('D'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, AMOUNTDC);
					$objPHPExcel->getActiveSheet()->getStyle('E'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$objPHPExcel->getActiveSheet()->getStyle('F'.$colVal)->applyFromArray(
								array('fill' 	=> array(
														'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
														'color'		=> array('argb' => 'FFFBB917'),
													)
								 )
							);

					$colVal		 = $colVal+1;
					foreach ($viewAccessList->result() as $key1=>$row1)
					{
						$objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($row1->accCode));
						$objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($row1->accName));
						$objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row1->mode));
						$objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row1->vFCBal));
						$objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($row1->vDCBal));

						$colVal++;
					}//end foreach

				}//end if
				$colVal++;
			}//end for each
		}//end if

		// Rename sheet
		$objPHPExcel->getActiveSheet()->setTitle(YEARCLOSINGDETAILS);
		$objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

		// Redirect output to a client's web browser (Excel5)
		header('Content-Type: application/vnd.ms-excel');
		header('Content-Disposition: attachment;filename="yearclosing_'.date('Y-m-d').'.xls"');
		header('Cache-Control: max-age=0');
		$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
		$objWriter->save('php://output');
	}//end function

