                    {
                        switch($row1->type)
                        {
                            case "Xo" :
                                $this->_TableName   = 'XoBooking';
                                $this->_extraField  = 'vXoNumber';
                                $this->dbId         = 'nXId';
                                break;

                            case "Ticket" :
                                $this->_TableName   = 'TicketBooking';
                                $this->_extraField  = 'vTicketNumber';
                                $this->dbId         = 'nTId';
                                break;

                            case "Hotel" :
                                $this->_TableName   = 'HotelVoucher';
                                $this->_extraField  = 'vVoucherId';
                                $this->dbId         = 'nHVId';
                                break;
                        }//end switch

