                        $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($row1->vPassenger));
                        $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($row1->vRemarks));
                        $colVal++;
                    }//end foreach
                }//end if
                $colVal++;
            }//end for each
        }//end if

        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(REFUNDREGISTERDETAILS);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="refundregister_'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

