    function xo_booking()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('I')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('J')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('K')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('L')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('M')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('N')->setWidth(10);
        $objPHPExcel->getActiveSheet()->getColumnDimension('O')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('P')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('Q')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('R')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('S')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('T')->setWidth(30);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', DIVISIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', TRANSNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', DOCNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('F1', TYPE);
        $objPHPExcel->getActiveSheet()->setCellValue('G1', AIRLINENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('H1', XONAME);
        $objPHPExcel->getActiveSheet()->setCellValue('I1', GDS);
        $objPHPExcel->getActiveSheet()->setCellValue('J1', BOOKEDBY);
        $objPHPExcel->getActiveSheet()->setCellValue('K1', ISSUEDBY);
        $objPHPExcel->getActiveSheet()->setCellValue('L1', PASSENGER);
        $objPHPExcel->getActiveSheet()->setCellValue('M1', ORIGINALTKT);
        $objPHPExcel->getActiveSheet()->setCellValue('N1', SEGMENT);
        $objPHPExcel->getActiveSheet()->setCellValue('O1', DESTINATION);
        $objPHPExcel->getActiveSheet()->setCellValue('P1', GDSPNR);
        $objPHPExcel->getActiveSheet()->setCellValue('Q1', AIRPNR);
        $objPHPExcel->getActiveSheet()->setCellValue('R1', CURRNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('S1', CURRRATE);

        $objPHPExcel->getActiveSheet()->getStyle('A1:T1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            foreach ($sqlArray->result() as $key=>$row)
            {
                $divName    = $this->common_model->get_field_name('Division','vTitle'," WHERE nId = '".$row->nDivision."'");
                $locName    = $this->common_model->get_field_name('Location','vCode'," WHERE nId = '".$row->nLocation."'");
                $dDate      = ($row->dDate != '0000-00-00')?date('d-m-Y',strtotime($row->dDate)):'NIL';

                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($divName));
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($locName));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $dDate);
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($this->common_model->get_field_name('Transactions','vTitle'," WHERE nId='".$row->nTransaction."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($this->common_model->get_field_name('Transactions','vSampledoc'," WHERE nId='".$row->nTransaction."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($row->vType));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($row->airlineName . ' (' . $row->airlineNo . ')'));
				$objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($row->vXoNumber));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($row->gdsName));
