                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($this->common_model->get_field_name('EmployeeMaster', 'vName', " WHERE nEId='" . $row->vIssuedBy . "' ")));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($row->traveller));
                $objPHPExcel->getActiveSheet()->setCellValue('M'.$colVal, stripslashes($row->vOriginalXo));
                $objPHPExcel->getActiveSheet()->setCellValue('N'.$colVal, stripslashes($row->vSegment));
                $objPHPExcel->getActiveSheet()->setCellValue('O'.$colVal, stripslashes($row->vDestination));
