                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($this->common_model->get_field_name('Airline','vAirlineNo', " WHERE nArId='".$row->nAirline."' ")));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, date('d-m-Y',strtotime($row->dDate)));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($this->common_model->get_field_name('EmployeeMaster','vCode', " WHERE nEId='".$row->vIssuedBy."' ")));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($row->vPassenger));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $sector);
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($row->Fare));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($row->totTax));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($row->Comm));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($row->netAmt));

                $colVal++;
            }//end foreach
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(UNPOST);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="_unpost_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

