                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$row->nLocation."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row->vAirpnr));
