        $objPHPExcel->getActiveSheet()->setCellValue('B1', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', AIRPNR);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', AIRCODE);
