        $objPHPExcel->getActiveSheet()->setCellValue('I1', FARE);
        $objPHPExcel->getActiveSheet()->setCellValue('J1', TAX);
        $objPHPExcel->getActiveSheet()->setCellValue('K1', COMMAMT);
        $objPHPExcel->getActiveSheet()->setCellValue('L1', NETAMT);
        $objPHPExcel->getActiveSheet()->setCellValue('M1', PROFIT);
        $objPHPExcel->getActiveSheet()->setCellValue('N1', PROFITPERCENTAGE);
        $objPHPExcel->getActiveSheet()->setCellValue('O1', STATUS);

