            foreach ($sqlArray->result() as $key=>$row)
            {
                $profit           = $row->netAmt-$row->salesAmt;
                if($profit >0 && $row->netAmt >0)
                    $profitPercentage = round((($profit*100)/$row->netAmt),2);
                else
                    $profitPercentage = 0;

                if(!in_array($row->account,$chkAccount)):
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($this->common_model->get_field_name('VendorMaster','vName'," WHERE nVId='".$row->account."'")));
                    $colVal++;
                endif;

                switch($row->sale_type)
                {
                    case "Ticket":
                        $sector = $this->common_model->get_field_name('TicketDetails','vSector1'," WHERE nTicketId='".$row->tableId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector1'," WHERE nTicketId='".$row->tableId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector2'," WHERE nTicketId='".$row->tableId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector3'," WHERE nTicketId='".$row->tableId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector4'," WHERE nTicketId='".$row->tableId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector44'," WHERE nTicketId='".$row->tableId."'");
                        break;

                    case "Xo":
                        $sector = $this->common_model->get_field_name('XoDetails','vSector'," WHERE nXoId='".$row->tableId."'").'-'.$this->common_model->get_field_name('XoDetails','vSector2'," WHERE nXoId='".$row->tableId."'");
                        break;
                }//end switch

                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($row->dDate));
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, stripslashes($this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$row->nLocation."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row->vAirpnr));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($this->common_model->get_field_name('Airline','vAirlineNo'," WHERE nArId='".$row->airline."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, stripslashes($row->tktNumber));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($this->common_model->get_field_name('EmployeeMaster', 'vName', " WHERE nEId='".$row->vIssuedBy."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($row->vPassenger));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($sector));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($row->fareVal));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($row->taxTotal));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($row->cmtAmount));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($row->netAmt));
                $objPHPExcel->getActiveSheet()->setCellValue('M'.$colVal, stripslashes($profit));
                $objPHPExcel->getActiveSheet()->setCellValue('N'.$colVal, stripslashes($profitPercentage));
                $objPHPExcel->getActiveSheet()->setCellValue('O'.$colVal, stripslashes($row->vStatus));

                $chkAccount[] = $row->account;
                $colVal++;
                $totalFare  = $totalFare+$row->fareVal;
                $totalTax   = $totalTax+$row->taxTotal;
                $totalComm  = $totalComm+$row->cmtAmount;
                $totalNet   = $totalNet+$row->netAmt;
                $totalProf  = $totalProf+$profit;
                $totalProP  = $totalProP+$profitPercentage;
            }//end foreach
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, TOTALAMT);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($totalFare));
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($totalTax));
            $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($totalComm));
            $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($totalNet));
            $objPHPExcel->getActiveSheet()->setCellValue('M'.$colVal, stripslashes($totalProf));
            $objPHPExcel->getActiveSheet()->setCellValue('N'.$colVal, stripslashes($totalProP));
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(PAYABLEACCOUNTSREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="_account_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

