		$objPHPExcel->getActiveSheet()->getStyle('I2:J2')->getAlignment()->setWrapText(true);

        $objPHPExcel->getActiveSheet()->setCellValue('A3', SRNO);
        $objPHPExcel->getActiveSheet()->setCellValue('B3', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('C3', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('D3', DOCUMENTNUMBER);
