        $objPHPExcel->getActiveSheet()->setCellValue('G3', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('H3', CREDIT);
        $objPHPExcel->getActiveSheet()->setCellValue('I3', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('J3', CREDIT);

        $objPHPExcel->getActiveSheet()->getStyle('A3:J3')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        if(trim($_SESSION['sess_opening']) == ''):
            $debitVal = $creditVal = $balanceVal = 0;
        else:
            $openSqlArray = $this->db->query($_SESSION['sess_opening']);
            if ($openSqlArray->num_rows() > 0)
            {
                $debit = 0;
                $credit = 0;
                foreach ($openSqlArray->result() as $key=>$row)
                {
                    $debit   += $row->debit;
                    $credit  += $row->credit;
                }//end for each
                $debitVal   = $debit;
                $creditVal  = $credit;
                $balanceVal = $debitVal - $creditVal;
            }
        endif;

        if(trim($_SESSION['sess_year']) == ''):
            $debitVal2 = $creditVal2 = $balanceVal2 = 0;
        else:
            $openSqlArray = $this->db->query($_SESSION['sess_year']);
            if ($openSqlArray->num_rows() > 0)
            {
                $debit2 = 0;
                $credit2 = 0;
                foreach ($openSqlArray->result() as $key=>$row)
                {
                    $debit2   += $row->DCTot;
                    $credit2  += $row->FCTot;
                }//end for each
                $debitVal2   = $debit2;
                $creditVal2  = $credit2;
                $balanceVal2 = $debitVal2 - $creditVal2;
            }
        endif;

        $objPHPExcel->getActiveSheet()->setCellValue('F4', YEARCLOSING);
        $objPHPExcel->getActiveSheet()->setCellValue('G4', $debitVal2);
        $objPHPExcel->getActiveSheet()->setCellValue('H4', $creditVal2);
        $objPHPExcel->getActiveSheet()->setCellValue('I4', $balanceVal2);

        $objPHPExcel->getActiveSheet()->setCellValue('F5', OPENINGBALANCE);
        $objPHPExcel->getActiveSheet()->setCellValue('G5', $debitVal);
        $objPHPExcel->getActiveSheet()->setCellValue('H5', $creditVal);
        $objPHPExcel->getActiveSheet()->setCellValue('I5', $balanceVal);

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 6;
        if ($sqlArray->num_rows() > 0)
        {
            $totalDebit = 0;
            $totalCredit = 0;
            $totalopenDebit = 0;

            $this->session->unset_userdata('newDebit');
            foreach ($sqlArray->result() as $key=>$row)
            {
                switch($row->tblName)
                {
                    case "CR":
                        $description = $row->description;
                        break;

                    case "CP":
                        $description = $row->description;
                        break;

                    case "BR":
                        $description = $row->description;
                        break;

                    case "BP":
                        $description = $row->description;
                        break;

                    case "JV":
                        $description = $row->description;
                        break;

                    case "SJ":
                        $salesDetId  = $this->common_model->get_field_name('SalesClosingDetails','nId'," WHERE nSalesCloseId='".$row->tableId."'");
                        $ticketType  = $this->common_model->get_field_name('SystemJvDetails','vType'," WHERE nSjDId='".$row->detId."'");
                        $ticketId    = $this->common_model->get_field_name('SystemJvDetails','vNumber'," WHERE nSjDId='".$row->detId."'");
                        switch($ticketType)
                        {
                            case "Xo" :
                                $description  = $this->common_model->get_field_name('XoDetails','vSector'," WHERE nXoId='".$ticketId."'").'-'.$this->common_model->get_field_name('XoDetails','vSector2'," WHERE nXoId='".$ticketId."'").'-'.date('d-m-Y',strtotime($this->common_model->get_field_name('XoDetails','dTravelDate'," WHERE nXoId='".$ticketId."'")));
                                $ticketNum    = $this->common_model->get_field_name('XoBooking','vTicktManual'," WHERE nXId='".$ticketId."'");
                                break;

                            case "Tkt" :
                                $description  = $this->common_model->get_field_name('TicketDetails','vSector1'," WHERE nTicketId='".$ticketId."'").'-'.$this->common_model->get_field_name('TicketDetails','vSector12'," WHERE nTicketId='".$ticketId."'").'-'.date('d-m-Y',strtotime($this->common_model->get_field_name('TicketDetails','dTravelDate1'," WHERE nTicketId='".$ticketId."'")));
                                $ticketNum    = $this->common_model->get_field_name('TicketBooking','vTicktManual'," WHERE nTId='".$ticketId."'");
                                break;

                            case "Htl" :
                                $cityName     = $this->common_model->get_field_name('HotelVoucher','nCity'," WHERE nHVId='".$ticketId."'");
                                $hotel        = $this->common_model->get_field_name('HotelVoucher','vHotelName'," WHERE nHVId='".$ticketId."'");
                                $description  = $this->common_model->get_field_name('Country','vName'," WHERE nId='".$cityName."'").'-'.$this->common_model->get_field_name('Hotel','vName'," WHERE nHId='".$hotel."'").'-'.date('d-m-Y',strtotime($this->common_model->get_field_name('HotelVoucher','dCheckIn'," WHERE nHVId='".$ticketId."'"))).'-'.date('d-m-Y',strtotime($this->common_model->get_field_name('HotelVoucher','dCheckOut'," WHERE nHVId='".$ticketId."'"))).'-'.$this->common_model->get_field_name('HotelVoucher','vNight'," WHERE nHVId='".$ticketId."'");
                                $ticketNum    = $this->common_model->get_field_name('HotelVoucher','vTicktManual'," WHERE nHVId='".$ticketId."'");
                                break;
                        }//end switch
                        break;

                    case "CV":
                        $description = $row->description;
                        break;

                    case "DV":
                        $description = $row->description;
                        break;

                    case "ACM":
                        $description = $row->description;
                        break;

                    case "ADM":
                        $description = $row->description;
                        break;
                }//end switch

                switch($row->mode)
                {
                    case "Dr":
                        $debit = $row->debit;
                        $credit = 0;
                        break;

                    case "Cr":
                        $debit = 0;
                        $credit = $row->debit;
                        break;

                    default:
                        $debit = ($row->debit==' ')?0:$row->debit;
                        $credit = ($row->credit==' ')?0:$row->credit;
                        break;
                }

                $openDebit = $this->ac_report_model->getCalDebit($debit,$credit);

                if($openDebit >= 0):
                    $totalopenDebit = $openDebit;
                endif;

                if($openDebit <= 0):
                    $openCredit = substr($openDebit,1,strlen($openDebit));
                    $totalopenCredit = $openCredit;
                endif;

                $srNo = $key+1;
                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($srNo));
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, date("d-M-y", strtotime($row->date)));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$row->location."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row->document));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, @str_replace("<br>","\n",$ticketNum));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, @str_replace("<br>","\n",$description));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($debit));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($credit));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($openDebit));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $openCredit);

                $totalDebit += $debit;
                $totalCredit += $credit;
                $colVal++;
            }//end foreach
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, TOTALAMOUNT);
            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $totalopenDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $totalopenCredit);
            $colVal++;
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, GRANDTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $totalopenDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $totalopenCredit);
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(DETAILREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="detail_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

