                        $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $getVal['wcredit']);
                        $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $getVal['openDebit']);
                        $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $getVal['openCredit']);

                endif;
                $totalDebit += $debit;
                $totalCredit += $credit;
                $totalopenDebit += $openDebit;
                if(!in_array($salesType,$chkTypeArray))
                    $chkDateArray[] = $row->date;
                $chkTypeArray[$row->date] = $salesType;

                $colVal++;
            }//end foreach
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, TOTALAMOUNT);
            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, '');
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, '');
            $colVal++;
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, GRANDTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, '');
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, '');
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(DAILYREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="daily_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

