        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('I')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('J')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('K')->setWidth(30);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', ACCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', ACCCODENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', SUBCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', SUBNAME);

        $objPHPExcel->getActiveSheet()->getStyle('A1')->getAlignment()->setWrapText(true);
        $objPHPExcel->getActiveSheet()->getStyle('B1')->getAlignment()->setWrapText(true);
        $objPHPExcel->getActiveSheet()->getStyle('C1')->getAlignment()->setWrapText(true);
        $objPHPExcel->getActiveSheet()->getStyle('D1')->getAlignment()->setWrapText(true);

        $objPHPExcel->getActiveSheet()->setCellValue('A2', '');
        $objPHPExcel->getActiveSheet()->setCellValue('B2', '');
        $objPHPExcel->getActiveSheet()->setCellValue('C2', '');
        $objPHPExcel->getActiveSheet()->setCellValue('D2', '');

        $objPHPExcel->getActiveSheet()->setCellValue('A3', SRNO);
        $objPHPExcel->getActiveSheet()->setCellValue('B3', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('C3', DOCUMENTNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('D3', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('E3', TICKETNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('F3', PASSENGERNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('G3', TRAVELSETUPDETAILS);
        $objPHPExcel->getActiveSheet()->setCellValue('H3', LPO);
        $objPHPExcel->getActiveSheet()->setCellValue('I3', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('J3', CREDIT);
        $objPHPExcel->getActiveSheet()->setCellValue('K3', BALANCE);

        $objPHPExcel->getActiveSheet()->getStyle('A3:K3')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 4;
        if ($sqlArray->num_rows() > 0)
        {
            foreach ($sqlArray->result() as $key=>$row)
            {
                switch($row->tblName)
                {
                    case "CR":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "CP":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "BR":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "BP":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "JV":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "SJ":
                        $lpoVal      = $this->common_model->get_field_name('SalesClosingDetails','vDLPO'," WHERE nSalesCloseId='".$row->tableId."'");
                        $getTktValue = $this->sub_report_model->getTktNumberValues($row->detId,$row->tableId);
                        $description = $getTktValue['desc'];
                        $ticketNum   = $getTktValue['tktVal'];
                        $passenger   = $getTktValue['passVal'];
                        break;

                    case "CV":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "DV":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "ACM":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;

                    case "ADM":
                        $description = $row->description;
                        $ticketNum   = '&nbsp';
                        break;
                }//end switch

                switch($row->mode)
                {
                    case "Dr":
                        $debit = $row->debit;
                        $credit = 0;
                        break;

                    case "Cr":
                        $debit = 0;
                        $credit = $row->debit;
                        break;

                    default:
                        $debit = ($row->debit==' ')?0:$row->debit;
                        $credit = ($row->credit==' ')?0:$row->credit;
                        break;
                }
                $balance = $debit-$credit;
                if($balance < 0):
                    $balance = substr($balance,1,strlen($balance));
                endif;

                $srNo = $key+1;
                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, stripslashes($srNo));
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, date("d-M-y", strtotime($row->date)));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($row->document));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$row->location."'")));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, @str_replace("<br>","\n",$ticketNum));
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, @str_replace("<br>","\n",$passenger));
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, @str_replace("<br>","\n",$description));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $lpoVal);
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, stripslashes($debit));
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, stripslashes($credit));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($balance));

                $objPHPExcel->getActiveSheet()->getStyle('E'.$colVal)->getAlignment()->setWrapText(true);
                $objPHPExcel->getActiveSheet()->getStyle('F'.$colVal)->getAlignment()->setWrapText(true);
                $objPHPExcel->getActiveSheet()->getStyle('G'.$colVal)->getAlignment()->setWrapText(true);

                $colVal++;
                $totalDebit   += $debit;
                $totalCredit  += $credit;
                $totalBalance = $balance;
            }//end foreach
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, TOTALAMOUNT);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, $totalBalance);

            $colVal++;

            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, GRANDTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, $totalBalance);
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(RECEIVABLEREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="receivable_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

