                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, '');
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, '');
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, '');
