        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('I')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('J')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('K')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('L')->setWidth(30);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', SRNO);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', DOCUMENTNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', ACCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('F1', ACCCODENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('G1', SUBCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('H1', SUBNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('I1', REFNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('J1', REFDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('K1', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('L1', CREDIT);

        $objPHPExcel->getActiveSheet()->getStyle('A1:L1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            foreach ($sqlArray->result() as $key=>$row)
            {
                switch($row->vTable)
                {
                    case "C":
                        $SubAccountName = $this->common_model->get_field_name('CustomerMaster','vName'," WHERE nCId='".$row->account."'");
                        $SubAccountCode = $this->common_model->get_field_name('CustomerMaster','vCode'," WHERE nCId='".$row->account."'");
                        break;

                    case "V":
                        $SubAccountName = $this->common_model->get_field_name('VendorMaster','vName'," WHERE nVId='".$row->account."'");
                        $SubAccountCode = $this->common_model->get_field_name('VendorMaster','vCode'," WHERE nVId='".$row->account."'");
                        break;

                    case "A":
                        $SubAccountName = $this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$row->account."'");
                        $SubAccountCode = $this->common_model->get_field_name('AccountHeadAccounts','vACode'," WHERE nId='".$row->account."'");
                        break;

                    case "O":
                        $SubAccountName = $this->common_model->get_field_name('Other','vName'," WHERE nOId='".$row->account."'");
                        $SubAccountCode = $this->common_model->get_field_name('Other','vCode'," WHERE nOId='".$row->account."'");
                        break;

                    case "AG":
                        $SubAccountName = $this->common_model->get_field_name('Agent','vName'," WHERE nAId='".$row->account."'");
                        $SubAccountCode = $this->common_model->get_field_name('Agent','vCode'," WHERE nAId='".$row->account."'");
                        break;

                    default:
                        $SubAccountCode = $this->common_model->get_field_name('AccountHeadAccounts','vACode'," WHERE nId='".$row->account."'");
                        $SubAccountName = $this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$row->account."'");
                        break;
                }

                $showCode = $this->common_model->get_field_name('AccountHeadAccounts','vACode'," WHERE nId='".$row->subacc."'");
                $showName = $this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$row->subacc."'");

                $srNo = $key+1;
                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $srNo);
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$row->location."'"));
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, date("d-M-y", strtotime($row->date)));
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, stripslashes($row->document));
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $SubAccountCode);
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $SubAccountName);
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($showCode));
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($showName));
                $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $row->vRefNumber);
                $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, date("d-M-y", strtotime($row->dRefDate)));
                $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, stripslashes($row->debit));
                $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, stripslashes($row->credit));
                $colVal++;
                $totalFC += $row->debit;
                $totalDC += $row->credit;
            }//end foreach

            $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, TOTALAMOUNT);
            $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, $totalFC);
            $objPHPExcel->getActiveSheet()->setCellValue('L'.$colVal, $totalDC);
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(TRANSACTIONREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="transaction_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

