    function account_group_report()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(40);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', ACCGROUPNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', OPENING);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', DURING);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', YEARTODATE);

        $objPHPExcel->getActiveSheet()->getStyle('A1:D1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            $j = 0;
            $flag = false;
            $chkGroupId = $chkHeadId = $chkAccountId = array();
            $totalPreviousLoop = $totalCurrentLoop = $totalPrevious = $totalCurrent = $totalOpenDebit = $totalOpenCredit = '';
            foreach ($sqlArray->result() as $key=>$row)
            {
                $mainId = $this->common_model->get_field_name('FinanceModule','vTitle'," WHERE nId='".$row->mainId."'");
                if($mainId=='3'):
                    $mainName = 'Income';
                elseif($mainId=='4'):
                    $mainName = 'Expense';
                endif;

                if(!in_array($mainId,$chkGroupId)):
                    if($j != 0):
                        $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, GROUPTOTAL);
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $totalPreviousLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalCurrentLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');
                        $colVal++;
                        $colVal++;
                        $flag = true;
                    endif;
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $mainName);
                    $colVal++;

                    $j = 1;
                endif;
                if(!in_array($row->HeadId,$chkHeadId)):
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->HeadName);
                    $colVal++;
                endif;

                if(!in_array($row->AccountId,$chkAccountId)):
                    $getValues          = $this->profloss_report_model->getAccValues($row->AccountId);
                    $getOpenValues      = $this->profloss_report_model->getOpenAccValues($row->AccountId);

                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->AccountName);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $getOpenValues['openDebit']);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $getValues['debit']);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');

                    $colVal++;
                    if($flag == true):
                        $totalPreviousLoop  = '';
                        $totalCurrentLoop   = '';
                        $flag               = false;
                    endif;

                    $chkGroupId[]            = $mainId;
                    $chkHeadId[]             = $row->HeadId;
                    $chkAccountId[]          = $row->AccountId;

                    $totalPrevious          += $getOpenValues['openDebit'];
                    $totalCurrent           += $getValues['debit'];
                    $totalPreviousLoop      += $getOpenValues['openDebit'];
                    $totalCurrentLoop       += $getValues['debit'];
                endif;

                if(($key+1) == count($sqlArray->result())):
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, GROUPTOTAL);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $totalPreviousLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalCurrentLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');
                    $colVal++;
                endif;

            }//end foreach

            $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, GRANDTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $totalPrevious);
            $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalCurrent);
            $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');

        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(PLACCOUNTGROUPREPORT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="account_group_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

