    function system_jv()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(30);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', SRNO);
		$objPHPExcel->getActiveSheet()->setCellValue('B1', DIVISIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', LOCATIONNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', JVNUMBER);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', DESCRIPTION);
        $objPHPExcel->getActiveSheet()->setCellValue('F1', CUSTDATE);
        $objPHPExcel->getActiveSheet()->setCellValue('G1', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('H1', CREDIT);

        $objPHPExcel->getActiveSheet()->getStyle('A1:H1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('rgb' => '90028f'),
            )
            )
        );


        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            $debitTotal = $creditTotal = 0;$chkSubCodeArray = array('82','72','91');
            foreach ($sqlArray->result() as $key=>$row)
            {
                $srNo = $key+1;

                switch($row->vType)
                {
                    case "Tkt":
                        $sType = 'Ticket';
                        break;

                    case "Xo":
                        $sType = 'Xo';
                        break;

                    case "Htl":
                        $sType = 'Hotel';
                        break;
                }//end switch

                $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $srNo);
                $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->dName);
                $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $row->lName);
                $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $row->vJVNo);
                $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $row->nInvoice);
                $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $row->dDate);
                $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, '');
                $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, '');
                $colVal++;

                $viewAccessList  = $this->db->query("SELECT sj.*,sjd.vType,sjd.vDes,sjd.nDebit,sjd.nCredit,sjd.vNumber,
											aha.vTitle as accName,aha.vACode as accCode,
										sad.vTable,sad.nDrAccount,l.vTitle as loc,d.vTitle as dName,
										l.vTitle as lName,sjd.nAccHeadId,
										CASE
											WHEN sad.vTable = 'c' THEN
										 		(SELECT vName FROM {PRE}CustomerMaster WHERE
										 			nCId = sad.nDrAccount)
											ELSE
												(SELECT vTitle FROM {PRE}AccountHeadAccounts WHERE
										 			nId = sad.nDrAccount)
										END as subCode,
										CASE
											WHEN sjd.vType = 'Tkt' THEN
										 		(SELECT vTicktManual FROM {PRE}TicketBooking WHERE
										 			nTId = sjd.vNumber)
											WHEN sjd.vType = 'Htl' THEN
										 		(SELECT vTicktManual FROM {PRE}HotelVoucher WHERE
										 			nHVId = sjd.vNumber)
											ELSE
												(SELECT vTicktManual FROM {PRE}XoBooking WHERE
										 			nXId = sjd.vNumber)
										END as tNumber
										 FROM {PRE}SystemJv sj
									LEFT JOIN {PRE}SystemJvDetails sjd ON sj.nId = sjd.nSjId
										LEFT JOIN {PRE}AccountHeadAccounts aha ON aha.nId = sjd.nAccHeadId
									LEFT JOIN {PRE}AccountHead ah ON ah.nAId = sjd.nAGId
										LEFT JOIN {PRE}SalesAccountDetails sad
								   ON sad.nSalesCloseId  = sj.nSalesCId
								   		LEFT JOIN {PRE}Division d ON d.nId = sj.nDivision
									LEFT JOIN {PRE}Location l ON l.nId = sj.nLocation
		                          			 WHERE sj.nId = '".$row->nId."' ORDER BY sj.nId DESC");
                if($viewAccessList->num_rows() > 0)
                {
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, LOCATIONNAME);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, ACCODE);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, SUBCODE);
                    $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, REFNUMBER);
                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, DESCRIPTION);
                    $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, DEBIT);
                    $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, CREDIT);

                    $objPHPExcel->getActiveSheet()->getStyle('A'.$colVal.':'.'H'.$colVal)->applyFromArray(
                        array('fill' 	=> array(
                            'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                            'color'		=> array('rgb' => '039003'),
                        )
                        )
                    );

                    $colVal++;

                    foreach ($viewAccessList->result() as $key1=>$details):
                        switch($details->vType)
                        {
                            case "Tkt":
                                $sType = 'Ticket';
                                break;

                            case "Xo":
                                $sType = 'Xo';
                                break;

                            case "Htl":
                                $sType = 'Hotel';
                                break;
                        }//end swithc

                        $showTktNo       = ($details->vNumber != 0)?($sType.'-'.$details->tNumber):'';

                        if($details->vNumber != 0):
                            $showSubCode = '';
                        else:
                            if(in_array($details->nAccHeadId,$chkSubCodeArray)):
                                $acCode      = $this->common_model->get_field_name('AccountHeadAccounts','nHAId'," WHERE nId = '".$details->nAccHeadId."'");
                                $showSubCode = $this->common_model->get_field_name('AccountHead','vAcname'," WHERE nAId = '".$acCode."'");
                            else:
                                $showSubCode = $details->subCode;
                            endif;
                        endif;

                        $debitTotal      += $details->nDebit;
                        $creditTotal     += $details->nCredit;

                        $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, '');
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $this->common_model->get_field_name('Location','vCode'," WHERE nId ='".$details->nLocation."'"));
                        $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, stripslashes($details->accName));
                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $showSubCode);
                        $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $showTktNo);
                        $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, stripslashes($details->vDes));
                        $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, stripslashes($details->nDebit));
                        $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, stripslashes($details->nCredit));
                        $colVal++;
                    endforeach;

                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, TOTALAMOUNT);
                    $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $debitTotal);
                    $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $creditTotal);

                    $colVal++;
                }//end if
                $colVal++;
            }//end foreach
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(SYSTEMJVMANAGEMENT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="system_jv'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

