        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(40);

        $objPHPExcel->getActiveSheet()->setCellValue('C1', OPENING);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', DURING);
        $objPHPExcel->getActiveSheet()->setCellValue('G1', BALANCE);

        $objPHPExcel->getActiveSheet()->getStyle('C1:D1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('rgb' => '039003'),
            )
            )
        );

        $objPHPExcel->getActiveSheet()->getStyle('E1:F1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('rgb' => '90028f'),
            )
            )
        );

        $objPHPExcel->getActiveSheet()->getStyle('G1:H1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('rgb' => '088A4B'),
            )
            )
        );

        $objPHPExcel->getActiveSheet()->setCellValue('A2', ACCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('B2', ACCCODENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C2', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('D2', CREDIT);
        $objPHPExcel->getActiveSheet()->setCellValue('E2', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('F2', CREDIT);
        $objPHPExcel->getActiveSheet()->setCellValue('G2', DEBIT);
        $objPHPExcel->getActiveSheet()->setCellValue('H2', CREDIT);

        $objPHPExcel->getActiveSheet()->getStyle('A2:H2')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 3;
        if ($sqlArray->num_rows() > 0)
        {
            $j = 0;
            $flag = false;
            $chkGroupId = $chkHeadId = $chkAccountId = array();
            $totalOpenDebitLoop = $totalOpenCreditLoop = $totalDebitLoop = $totalCreditLoop = $totalBalanceDebitLoop = $totalBalanceCreditLoop = '';
            $totalOpenDebit = $totalOpenCredit = $totalDebit = $totalCredit = $totalBalanceDebit = $totalBalanceCredit = '';
            foreach ($sqlArray->result() as $key=>$row)
            {
                if(!in_array($row->HeadId,$chkHeadId)):
                    if($j != 0):
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GROUPTOTAL);
                        $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalOpenDebitLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $totalOpenCreditLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $totalDebitLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $totalCreditLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalBalanceDebitLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalBalanceCreditLoop);
                        $colVal++;
                        $colVal++;
                        $flag = true;
                    endif;
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->HeadCode);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->HeadName);
                    $colVal++;

                    $j = 1;
                endif;

                if(!in_array($row->AccountId,$chkAccountId)):

                    $getSubValues   = $this->trial_report_model->getAllSubAccValues($row->AccountId);
                    $getOpenValues  = $this->trial_report_model->getAllSubOpenValues($row->AccountId);

                    if(!empty($getSubValues)):

                        $chkDebit   = $getSubValues['debit'];
                        $chkCredit  = $getSubValues['credit'];
                        $chkSubId 	= $getSubValues['sub'];
                        $chkTable 	= $getSubValues['table'];
                        $openCredit = $getOpenValues['openCredit'];
                        $openDebit 	= $getOpenValues['openDebit'];
                        $tnumber    = $getSubValues['tnumber'];
                        $totalOpenDebit2     = 0;
                        $totalOpenCredit2    = 0;
                        $totalDebit2         = 0;
                        $totalCredit2        = 0;
                        $totalBalanceDebit2  = 0;
                        $totalBalanceCredit2 = 0;

                        foreach($chkDebit as $key2 => $row2):
                            $getBalance     = ($openDebit[$key2]-$openCredit[$key2])+($chkDebit[$key2]-$chkCredit[$key2]);
                            if($getBalance > 0):
                                $balanceDebit = $getBalance;
                                $balanceCredit = '';
                            else:
                                $balanceDebit = '';
                                $balanceCredit = substr($getBalance,1,strlen($getBalance));
                            endif;

                            if($chkSubId[$key2] !=0):
                                switch($chkTable[$key2])
                                {
                                    case "C":
                                        $SubAccountName = $this->common_model->get_field_name('CustomerMaster','vName'," WHERE nCId='".$chkSubId[$key2]."'");
                                        $SubAccountCode = $this->common_model->get_field_name('CustomerMaster','vCode'," WHERE nCId='".$chkSubId[$key2]."'");
                                        break;

                                    case "V":
                                        $SubAccountName = $this->common_model->get_field_name('VendorMaster','vName'," WHERE nVId='".$chkSubId[$key2]."'");
                                        $SubAccountCode = $this->common_model->get_field_name('VendorMaster','vCode'," WHERE nVId='".$chkSubId[$key2]."'");
                                        break;

                                    case "A":
                                        $SubAccountName = $this->common_model->get_field_name('AccountHeadAccounts','vTitle'," WHERE nId='".$chkSubId[$key2]."'");
                                        $SubAccountCode = $this->common_model->get_field_name('AccountHeadAccounts','vACode'," WHERE nId='".$chkSubId[$key2]."'");
                                        break;

                                    case "O":
                                        $SubAccountName = $this->common_model->get_field_name('Other','vName'," WHERE nOId='".$chkSubId[$key2]."'");
                                        $SubAccountCode = $this->common_model->get_field_name('Other','vCode'," WHERE nOId='".$chkSubId[$key2]."'");
                                        break;

                                    case "AG":
                                        $SubAccountName = $this->common_model->get_field_name('Agent','vName'," WHERE nAId='".$chkSubId[$key2]."'");
                                        $SubAccountCode = $this->common_model->get_field_name('Agent','vCode'," WHERE nAId='".$chkSubId[$key2]."'");
                                        break;

                                    default:
                                        $SubAccountName = $row->AccountName;
                                        $SubAccountCode = $row->AccountCode;
                                        break;
                                }//end switch
                            else:
                                $SubAccountName = $row->AccountName;
                                $SubAccountCode = $row->AccountCode;
                            endif;

                            if($SubAccountName == 'BSP Payable'):
                                $getCode     = $this->common_model->get_field_name('TicketFareDetails','nAcc',
                                    " WHERE nTicketId  = '".$tnumber[$key2]."'");
                                $SubAccountName = $this->common_model->get_field_name('VendorMaster','vName',
                                    " WHERE nVId  = '".$getCode."'");
                            elseif($SubAccountName == 'Tour Agent & Hotels Payable'):
                                $getCode     = $this->common_model->get_field_name('HotelVoucher','nAcCode',
                                    " WHERE nHVId  = '".$tnumber[$key2]."'");
                                $SubAccountName = $this->common_model->get_field_name('VendorMaster','vName',
                                    " WHERE nVId  = '".$getCode."'");
                            elseif($SubAccountName == 'XO Payable'):
                                $getCode     = $this->common_model->get_field_name('XoBooking','nPassengerAC',
                                    " WHERE nXId = '".$tnumber[$key2]."'");
                                $SubAccountName = $this->common_model->get_field_name('VendorMaster','vName',
                                    " WHERE nVId  = '".$getCode."'");
                            else:
                                $SubAccountName = $SubAccountName;
                            endif;

                            $totalOpenDebit2     += $openDebit[$key2];
                            $totalOpenCredit2    += $openCredit[$key2];
                            $totalDebit2         += $chkDebit[$key2];
                            $totalCredit2        += $chkCredit[$key2];
                            $totalBalanceDebit2  += $balanceDebit;
                            $totalBalanceCredit2 += $balanceCredit;

                            $ValSubAccountCode = ($chkName != $SubAccountName)?$SubAccountCode:$SubAccountCode;
                            $ValSubAccountName = ($chkName != $SubAccountName)?$SubAccountName:$SubAccountName;
                            $ValTotalOpenDebit2 = ($chkName != $SubAccountName)?$openDebit[$key2]:$totalOpenDebit2;
                            $ValTotalOpenCredit2 = ($chkName != $SubAccountName)?$openCredit[$key2]:$totalOpenCredit2;
                            $ValTotalDebit2 = ($chkName != $SubAccountName)?$chkDebit[$key2]:$totalDebit2;
                            $ValTotalCredit2 = ($chkName != $SubAccountName)?$chkCredit[$key2]:$totalCredit2;
                            $ValTotalBalanceDebit2 = ($chkName != $SubAccountName)?$balanceDebit:$totalBalanceDebit2;
                            $ValTotalBalanceCredit2 = ($chkName != $SubAccountName)?$balanceCredit:$totalBalanceCredit2;

                            $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $ValSubAccountCode);
                            $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $ValSubAccountName);
                            $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $ValTotalOpenDebit2);
                            $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $ValTotalOpenCredit2);
                            $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $ValTotalDebit2);
                            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $ValTotalCredit2);
                            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $ValTotalBalanceDebit2);
                            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $ValTotalBalanceCredit2);
                            $colVal++;

                            $totalOpenDebit     += $openDebit[$key2];
                            $totalOpenCredit    += $openCredit[$key2];
                            $totalDebit         += $chkDebit[$key2];
                            $totalCredit        += $chkCredit[$key2];
                            $totalBalanceDebit  += $balanceDebit;
                            $totalBalanceCredit += $balanceCredit;

                            $chkName = $SubAccountName;

                            if($flag == true):
                                $totalOpenDebitLoop  = '';
                                $totalOpenCreditLoop = '';
                                $totalDebitLoop      = '';
                                $totalCreditLoop     = '';
                                $totalBalanceDebitLoop = '';
                                $totalBalanceCreditLoop = '';
                                $flag                = false;
                            endif;

                            $chkGroupId[]            = $row->GroupId;
                            $chkHeadId[]             = $row->HeadId;
                            $chkAccountId[]          = $row->AccountId;
                            $chkSubAccount[]         = $SubAccountName;

                            $totalOpenDebitLoop     += $openDebit[$key2];
                            $totalOpenCreditLoop    += $openCredit[$key2];
                            $totalDebitLoop         += $chkDebit[$key2];
                            $totalCreditLoop        += $chkCredit[$key2];
                            $totalBalanceDebitLoop  += $balanceDebit;
                            $totalBalanceCreditLoop += $balanceCredit;
                        endforeach;
                    endif;
                endif;
                if(($key+1) == count($sqlArray->result())):
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GROUPTOTAL);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalOpenDebitLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $totalOpenCreditLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $totalDebitLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $totalCreditLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalBalanceDebitLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalBalanceCreditLoop);
                    $colVal++;
                endif;

            }//end foreach

            $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GRANDTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalOpenDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $totalOpenCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $totalDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $totalCredit);
            $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalBalanceDebit);
            $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalBalanceCredit);

        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(SUBGROUPWITHSUBACCOUNT);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="sub_account_group_trial'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

    function general_details_report()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(40);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', ACCODE);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', ACCCODENAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', LASTYEAR);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', CURRENTYEAR);

        $objPHPExcel->getActiveSheet()->getStyle('A1:D1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            $j = 0;
            $flag = false;
            $chkGroupId = $chkHeadId = $chkAccountId = array();
            $totalPreviousLoop = $totalCurrentLoop = $totalPrevious = $totalCurrent = '';

            foreach ($sqlArray->result() as $key=>$row)
            {
                $srNo = $key+1;
                $mainId = $this->common_model->get_field_name('FinanceModule','vTitle'," WHERE nId='".$row->mainId."'");
                if($mainId=='1'):
                    $mainCode = '1';
                    $mainName = 'Asset';
                elseif($mainId=='2'):
                    $mainCode = '2';
                    $mainName = 'Liabilities';
                endif;

                if(!in_array($mainId,$chkGroupId)):
                    if($j != 0):
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GROUPTOTAL);
                        $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalPreviousLoop);
                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $totalCurrentLoop);
                        $colVal++;
                        $colVal++;
                        $flag = true;
                    endif;
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $mainCode);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $mainName);
                    $colVal++;

                    $j = 1;
                endif;
                if(!in_array($row->HeadId,$chkHeadId)):
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->HeadCode);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->HeadName);
                    $colVal++;

                endif;

                if(!in_array($row->AccountId,$chkAccountId)):

                    $getValues          = $this->balasheet_report_model->getAccValues($row->AccountId);
                    $getOpenValues      = $this->balasheet_report_model->getOpenAccValues($row->AccountId);
                    $balanceDebit       = ($getOpenValues['openDebit']-$getOpenValues['openCredit'])+($getValues['debit']-$getValues['credit']);
                    if($mainId==2)
                        $balanceDebit = $balanceDebit*-1;

                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->AccountCode);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->AccountName);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $getOpenValues['openDebit']);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $balanceDebit);
                    $colVal++;

                    if($flag == true):
                        $totalPreviousLoop  = '';
                        $totalCurrentLoop   = '';
                        $flag               = false;
                    endif;

                    $chkGroupId[]            = $mainId;
                    $chkHeadId[]             = $row->HeadId;
                    $chkAccountId[]          = $row->AccountId;

                    $totalPrevious          += $getOpenValues['openDebit'];
                    $totalCurrent           += $balanceDebit;
                    $totalPreviousLoop      += $getOpenValues['openDebit'];
                    $totalCurrentLoop       += $balanceDebit;

                endif;

                if(($key+1) == count($sqlArray->result())):
                    $getPL  = $this->balasheet_report_model->getPLValues();
                    $totalPreviousLoop += $getPL['previous'];
                    $totalCurrentLoop += $getPL['current'];

                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $getPL['acCode']);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $getPL['acName']);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $getPL['previous']);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $getPL['current']);
                    $colVal++;

                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GROUPTOTAL);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalPreviousLoop);
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $totalCurrentLoop);
                    $colVal++;
                endif;

            }//end foreach
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(BALANCESHEETGENERAL);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="general_details_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

