        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(40);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', LIABILITIES);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', '');
        $objPHPExcel->getActiveSheet()->setCellValue('C1', BALANCE);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', ASSETS);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', '');
        $objPHPExcel->getActiveSheet()->setCellValue('F1', BALANCE);

