            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        $colVal2     = 2;
        if ($sqlArray->num_rows() > 0)
        {
            $chkGroupId = $chkHeadId = $chkAccountId = array();
            $totalCurrentLoop2 = '';
            foreach($sqlArray->result() as $key => $row):
                $mainId = $this->common_model->get_field_name('FinanceModule','vTitle'," WHERE nId='".$row->mainId."'");
                if($mainId == '2') :
                    if(!in_array($row->HeadId,$chkHeadId)):

                        $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->HeadCode);
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->HeadName);
                        $colVal++;
                    endif;

                    if(!in_array($row->AccountId,$chkAccountId)):

                        $getValues          = $this->balasheet_report_model->getBalanceAccValues($row->AccountId,$mainId);
                        $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $row->AccountCode);
                        $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $row->AccountName);
                        $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $getValues['debit']);
                        $colVal++;

                        $chkGroupId[]            = $mainId;
                        $chkHeadId[]             = $row->HeadId;
                        $chkAccountId[]          = $row->AccountId;

                        $totalCurrentLoop2       += $getValues['debit'];
                    endif;
                endif;
            endforeach;

            $getPL  = $this->balasheet_report_model->getPLValues();
            $totalCurrentLoop2 += $getPL['current'];
            $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, GROUPTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $totalCurrentLoop2);
            $colVal++;

            $chkGroupId = $chkHeadId = $chkAccountId = array();
            $totalCurrentLoop = '';
            foreach($sqlArray->result() as $key => $row):
                $mainId = $this->common_model->get_field_name('FinanceModule','vTitle'," WHERE nId='".$row->mainId."'");
                if($mainId == '1') :
                    if(!in_array($row->HeadId,$chkHeadId)):

                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal2, $row->HeadCode);
                        $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal2, $row->HeadName);
                        $colVal2++;
                    endif;

                    if(!in_array($row->AccountId,$chkAccountId)):

                        $getValues          = $this->balasheet_report_model->getBalanceAccValues($row->AccountId,$mainId);
                        $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal2, $row->AccountCode);
                        $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal2, $row->AccountName);
                        $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal2, $getValues['debit']);
                        $colVal2++;

                        $chkGroupId[]            = $mainId;
                        $chkHeadId[]             = $row->HeadId;
                        $chkAccountId[]          = $row->AccountId;

                        $totalCurrentLoop       += $getValues['debit'];
                    endif;
                endif;
            endforeach;

            $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal2, GROUPTOTAL);
            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal2, $totalCurrentLoop);
            $colVal2++;

        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(BALANCESHEETGENERAL);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="balance_sheet_report'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

    function chart_account_group()
    {
        $this->common_model->check_admin_authorization();
        session_start();

        require_once 'static/classes/Classes/PHPExcel.php';
        require_once 'static/classes/Classes/PHPExcel/IOFactory.php';

        // Create new PHPExcel object
        $objPHPExcel = new PHPExcel();
        //set column width
        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(40);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(40);

        $objPHPExcel->getActiveSheet()->setCellValue('A1', CODE);
        $objPHPExcel->getActiveSheet()->setCellValue('B1', GROUPNAME);
        $objPHPExcel->getActiveSheet()->setCellValue('C1', GROUP);
        $objPHPExcel->getActiveSheet()->setCellValue('D1', DESCRIPTION);
        $objPHPExcel->getActiveSheet()->setCellValue('E1', CODE);
        $objPHPExcel->getActiveSheet()->setCellValue('F1', SUBGROUPNAME);

        $objPHPExcel->getActiveSheet()->getStyle('A1:F1')->applyFromArray(
            array('fill' 	=> array(
                'type'		=> PHPExcel_Style_Fill::FILL_SOLID,
                'color'		=> array('argb' => 'FF306EFF'),
            )
            )
        );

        $sqlArray    = $this->db->query($_SESSION['sess_query']);
        $colVal      = 2;
        if ($sqlArray->num_rows() > 0)
        {
            $chkMainCode = array();
            $chkMainGroup   = array();
            foreach ($sqlArray->result() as $key=>$row)
            {
                switch($row->vTitle)
                {
                    case "1" :
                        $mainGroup = 'Assets';
                        $mainCode  = '1';
                        break;

                    case "2" :
                        $mainGroup = 'Liability';
                        $mainCode  = '2';
                        break;

                    case "3" :
                        $mainGroup = 'Income';
                        $mainCode  = '3';
                        break;

                    case "4" :
                        $mainGroup = 'Expense';
                        $mainCode  = '4';
                        break;
                }//end switch

                if(!in_array($mainCode,$chkMainCode)):
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, $mainCode);
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, $mainGroup);
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, '');
                    $colVal++;
                endif;
                    $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, $this->common_model->get_field_name('FinanceModule','vCode'," WHERE nParent='".$row->nId."'"));
                    $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, $this->common_model->get_field_name('FinanceModule','vTitle'," WHERE nParent='".$row->nId."'"));
                    $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, '');
                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, '');

                    $colVal++;

                    $finance =  $this->common_model->get_field_name('FinanceModule','nId'," WHERE nParent='".$row->nId."'");
                    $viewAccessList  = $this->db->query("SELECT ah.vHCode,ah.vAcname,ah.nAId,ah.nAGroup FROM {PRE}FinanceModule fm
                                             LEFT JOIN {PRE}AccountHead ah ON fm.nId = ah.nAGroup
                                             WHERE ah.vActive = '1' AND fm.nId='".$finance."' ORDER BY ah.nAId ASC");
                    if($viewAccessList->num_rows() > 0):
                        foreach($viewAccessList->result() as $key1=>$accItem):
                            $objPHPExcel->getActiveSheet()->setCellValue('A'.$colVal, '');
                            $objPHPExcel->getActiveSheet()->setCellValue('B'.$colVal, '');
                            $objPHPExcel->getActiveSheet()->setCellValue('C'.$colVal, '');
                            $objPHPExcel->getActiveSheet()->setCellValue('D'.$colVal, '');
                            $objPHPExcel->getActiveSheet()->setCellValue('E'.$colVal, $accItem->vHCode);
                            $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, $accItem->vAcname);
                            $colVal++;
                        endforeach;
                    endif;

                    $chkMainCode[] = $mainCode;
                    $chkMainGroup[] = $mainGroup;
                $colVal++;

            }//end foreach
        }//end if

        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(ACCOUNTGROUPLIST);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="chart_account_group'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

