                        $totalPaid      += $tkt->vPaidAmt;
                        $colVal++;
                    endforeach;

                    $colVal++;

                    $objPHPExcel->getActiveSheet()->setCellValue('F'.$colVal, TOTALAMT);
                    $objPHPExcel->getActiveSheet()->setCellValue('G'.$colVal, $totalNet);
                    $objPHPExcel->getActiveSheet()->setCellValue('H'.$colVal, $totalSerP);
                    $objPHPExcel->getActiveSheet()->setCellValue('I'.$colVal, $totalSer);
                    $objPHPExcel->getActiveSheet()->setCellValue('J'.$colVal, $totalAgent);
                    $objPHPExcel->getActiveSheet()->setCellValue('K'.$colVal, $totalPaid);

                    $colVal++;
                }//end if
                $colVal++;
            }//end foreach
        }//end if
        // Rename sheet
        $objPHPExcel->getActiveSheet()->setTitle(COUNTRYCITYLIST);
        $objPHPExcel->getActiveSheet()->getTabColor()->setRGB('FFB6C1');

        // Redirect output to a client's web browser (Excel5)
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="refund_reprint'.date('Y-m-d').'.xls"');
        header('Cache-Control: max-age=0');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        $objWriter->save('php://output');
    }//end function

    function generate_xl(){

      $this->common_model->check_admin_authorization();
      session_start();

      $sess_data_name = $this->uri->segment(4);
      $CustomerValueArray = $_SESSION[$sess_data_name];
      $download_fileName = date('Y-m-d').'_'.time().$sess_data_name;
      $this->common_model->exportAsExcel_H($CustomerValueArray,$download_fileName);



    }//end function

}//end class

